export default async function install(app) {
 const details=app.getMount("park-details"), navigator=app.getMount("park-navigator"), layer=app.layers[app.config.layerId];app.assert(layer,"National Parks layer is unavailable.");let parks=[], request=0;
 const notice=(target,kind,title,message)=>{const n=document.createElement("calcite-notice");n.open=true;n.setAttribute("kind",kind);const h=document.createElement("div");h.slot="title";h.textContent=title;const m=document.createElement("div");m.slot="message";m.textContent=message;n.append(h,m);target.replaceChildren(n)};
 const row=(label,value)=>{const r=document.createElement("div");r.style.cssText="display:grid;grid-template-columns:92px minmax(0,1fr);gap:8px;padding:8px 0;border-top:1px solid var(--app-border-subtle)";const k=document.createElement("span");k.textContent=label;k.style.cssText="color:var(--app-text-muted);font-size:12px";const v=document.createElement("span");v.textContent=value||"Not listed";v.style.cssText="color:var(--app-text);font-weight:600;overflow-wrap:anywhere";r.append(k,v);return r};
 const idle=()=>notice(details,"info","Choose a park","Select a boundary or choose a park from the list.");
 app.actions.register("show-park-details",async({graphic})=>{const current=++request;const load=document.createElement("calcite-loader");load.style.cssText="display:block;margin:24px auto";details.replaceChildren(load);try{await layer.load();const q=await layer.queryFeatures({objectIds:[graphic.getObjectId()],outFields:["PARKNAME","UNIT_NAME","STATE","REGION","UNIT_TYPE","Status","UNIT_CODE","IRMAReference"],returnGeometry:false});if(current!==request)return;const a=q.features[0]?.attributes||{},p=document.createElement("calcite-panel");p.setAttribute("heading",a.PARKNAME||a.UNIT_NAME||"National Park");p.setAttribute("description",[a.STATE,a.REGION].filter(Boolean).join(" • ")||"National Park Service unit");p.setAttribute("icon","tree");const chip=document.createElement("calcite-chip");chip.setAttribute("kind","success");chip.textContent=a.Status||a.UNIT_TYPE||"National Park Service";chip.style.margin="0 0 12px";const d=document.createElement("div");d.append(row("Official unit",a.UNIT_NAME),row("State",a.STATE),row("Region",a.REGION),row("Unit type",a.UNIT_TYPE),row("Unit code",a.UNIT_CODE),row("IRMA reference",a.IRMAReference));p.append(chip,d);details.replaceChildren(p)}catch(e){if(current===request)notice(details,"danger","Details unavailable","Try selecting the park again.")}});
 app.actions.register("navigate-to-park",async({objectId})=>{const park=parks.find(x=>String(x.objectId)===String(objectId));if(!park)return{opened:false};await app.view.goTo(park.geometry,{duration:850});await app.actions.invoke("show-park-details",{graphic:park.graphic,selection:{layerId:layer.id,ids:[String(park.objectId)],count:1}});return{opened:true,park:park.name}});
 const renderList=()=>{const list=document.createElement("calcite-list");list.setAttribute("label","National parks");list.setAttribute("selection-mode","single");list.setAttribute("filter-enabled","");list.setAttribute("filter-placeholder","Find a park");list.style.cssText="max-height:calc(100vh - 210px);overflow:auto";list.filterProps=["label","description"];for(const p of parks){const i=document.createElement("calcite-list-item");i.setAttribute("label",p.name);i.setAttribute("description",[p.state,p.type].filter(Boolean).join(" • ")||"National Park Service unit");i.setAttribute("value",String(p.objectId));i.setAttribute("icon-start","tree");list.append(i)}const change=async()=>{const s=list.selectedItems&&list.selectedItems[0];if(!s)return;try{await app.actions.invoke("navigate-to-park",{objectId:s.value})}catch(e){notice(navigator,"danger","Unable to open park","Try selecting the park again.")}};list.addEventListener("calciteListChange",change);app.onCleanup(()=>list.removeEventListener("calciteListChange",change));navigator.replaceChildren(list)};
 idle();const load=document.createElement("calcite-loader");load.style.cssText="display:block;margin:24px auto";navigator.replaceChildren(load);try{await layer.load();const q=layer.createQuery();q.where="UNIT_TYPE = 'National Parks'";q.outFields=["OBJECTID","PARKNAME","UNIT_NAME","STATE","UNIT_TYPE"];q.returnGeometry=true;q.orderByFields=["PARKNAME ASC"];const r=await layer.queryFeatures(q),seen=new Set();parks=r.features.map(g=>({graphic:g,objectId:g.getObjectId(),name:String(g.attributes.PARKNAME||g.attributes.UNIT_NAME||"National Park"),state:String(g.attributes.STATE||""),type:String(g.attributes.UNIT_TYPE||""),geometry:g.geometry})).filter(p=>{const key=`${p.name}|${p.state}`;if(!p.geometry||seen.has(key))return false;seen.add(key);return true});renderList()}catch(e){notice(navigator,"danger","Park list unavailable","The national parks could not be loaded right now.")}app.onCleanup(()=>{details.replaceChildren();navigator.replaceChildren()});
}